1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: QuoteStep[];
20	};
21	
22	export type ScenarioResult = {
23	  results: unknown[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	
29	/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
30	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
31	
32	/** The item types the MHPCO will insure, and what each costs to cover. */
33	const BASE_PREMIUMS: Record<string, number | undefined> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	/** Premium for a single item of this type. `undefined` for a type the MHPCO does not insure — rejecting those is not yet specified by a test. */
43	const unitPremiumFor = (type: string): number | undefined => BASE_PREMIUMS[type];
44	
45	/** Component types that form discounted blocks. */
46	const BLOCK_FORMING_COMPONENTS = new Set(["rune", "moonstone"]);
47	const COMPONENT_BLOCK_SIZE = 3;
48	const COMPONENT_BLOCK_PREMIUM = 60;
49	
50	const formsComponentBlock = (type: string, count: number): boolean =>
51	  BLOCK_FORMING_COMPONENTS.has(type) && count === COMPONENT_BLOCK_SIZE;
52	
53	const countByType = (items: Item[]): Map<string, number> => {
54	  const counts = new Map<string, number>();
55	  for (const item of items) {
56	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
57	  }
58	  return counts;
59	};
60	
61	/** Alike components form a discounted block; everything else is priced per unit. */
62	const basePremiumForGroup = (type: string, count: number): number => {
63	  if (formsComponentBlock(type, count)) return COMPONENT_BLOCK_PREMIUM;
64	  const unitPremium = unitPremiumFor(type);
65	  // An uninsurable type yields NaN, which propagates to the quote. Rejecting
66	  // unknown types with a real error is specified by a test we have not reached yet.
67	  return unitPremium === undefined ? NaN : count * unitPremium;
68	};
69	
70	const policyBasePremium = (items: Item[]): number =>
71	  [...countByType(items)].reduce(
72	    (total, [type, count]) => total + basePremiumForGroup(type, count),
73	    0,
74	  );
75	
76	/** A modifier that applies to some subject, contributing a rate when it does. */
77	type ModifierRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
78	
79	/** Modifier rates stack additively — at both the item and the policy level. */
80	const sumApplicableRates = <Subject>(
81	  rules: ModifierRule<Subject>[],
82	  subject: Subject,
83	): number =>
84	  rules.reduce((total, rule) => (rule.applies(subject) ? total + rule.rate : total), 0);
85	
86	const CURSE_SURCHARGE_RATE = 0.5;
87	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
88	const HIGH_ENCHANTMENT_THRESHOLD = 5;
89	
90	/** Each risk an item can carry, and the surcharge rate it attracts. */
91	const ITEM_SURCHARGE_RULES: ModifierRule<Item>[] = [
92	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
93	  {
94	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
95	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
96	  },
97	];
98	
99	/** Item-level surcharge rates stack additively on one item. */
100	const surchargeRateFor = (item: Item): number =>
101	  sumApplicableRates(ITEM_SURCHARGE_RULES, item);
102	
103	/**
104	 * Item-level surcharges apply to the affected item's own base premium, not to
105	 * the policy total. An uninsurable type yields NaN and propagates to the quote,
106	 * as in `basePremiumForGroup`.
107	 */
108	const itemSurchargeTotal = (items: Item[]): number =>
109	  items.reduce(
110	    (total, item) => total + (unitPremiumFor(item.type) ?? NaN) * surchargeRateFor(item),
111	    0,
112	  );
113	
114	const LOYALTY_DISCOUNT_RATE = 0.2;
115	const LOYALTY_YEARS_THRESHOLD = 2;
116	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
117	
118	/** A quote in the context of the customer's history with the MHPCO. */
119	type Contract = {
120	  customer: Customer;
121	  /** How many contracts this customer already held when this quote was made. */
122	  precedingContracts: number;
123	};
124	
125	/** Each policy-level modifier, and the rate it contributes. Discounts are negative. */
126	const POLICY_MODIFIER_RULES: ModifierRule<Contract>[] = [
127	  {
128	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
129	    rate: -LOYALTY_DISCOUNT_RATE,
130	  },
131	  // Every quote insures its items for the first time, whatever the customer's history.
132	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE },
133	  {
134	    applies: ({ precedingContracts }) => precedingContracts > 0,
135	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
136	  },
137	];
138	
139	/**
140	 * Policy-level modifiers are percentages of the policy base premium and stack
141	 * additively, per the MHPCO's worked examples.
142	 */
143	const policyModifierRate = (contract: Contract): number =>
144	  sumApplicableRates(POLICY_MODIFIER_RULES, contract);
145	
146	const quotePremium = (items: Item[], contract: Contract): number => {
147	  const policyBase = policyBasePremium(items) + itemSurchargeTotal(items);
148	  const withPolicyModifiers = policyBase * (1 + policyModifierRate(contract));
149	  const withProcessingFee = withPolicyModifiers + PROCESSING_FEE;
150	  return roundUpToWholeG(withProcessingFee);
151	};
152	
153	export const runScenario = (scenario: Scenario): ScenarioResult => {
154	  return {
155	    results: scenario.steps.map((step, index) => ({
156	      premium: quotePremium(step.items, {
157	        customer: scenario.customer,
158	        precedingContracts: index,
159	      }),
160	    })),
161	  };
162	};
